fn count_close(seg: String) -> Int {
  return len(split(seg, ")")) - 1
}

fn balanced_parens(s: String) -> Bool {
  let segs = split(s, "(")
  var depth = 0
  for pair in enumerate(segs) {
    if pair.0 > 0 {
      depth = depth + 1
    }
    depth = depth - count_close(pair.1)
    if depth < 0 {
      return false
    }
  }
  return depth == 0
}

