type Student {
  name: String,
  scores: List[Int],
}

fn average(scores: List[Int]) -> Int {
  let n = len(scores)
  if n == 0 {
    return 0
  }
  return sum(scores) / n
}

fn grade(avg: Int) -> String {
  if avg >= 90 {
    return "A"
  }
  if avg >= 80 {
    return "B"
  }
  if avg >= 70 {
    return "C"
  }
  if avg >= 60 {
    return "D"
  }
  return "F"
}

fn report_card(students: List[Student]) -> List[(String, String)] {
  return map(students, |s| (s.name, grade(average(s.scores))))
}

